'use strict';
const COMMUNITY={me:null,epoch:0,draft:null,files:[],savePromise:null,topic:null,offset:0};
const communityKinds=['寻求帮助','经历交流','资料整理','保存与传播'];
const communityStatuses={draft:'未提交草稿',pending:'等待审核',published:'已公开',hidden:'暂时隐藏',needs_changes:'需要修改',withdrawn:'已撤回'};
const communityProgress={open:'仍需帮助',ongoing:'正在处理',solved:'已有进展'};
function communitySize(n){return n<1024*1024?Math.ceil(n/1024)+' KB':(n/1024/1024).toFixed(1)+' MB'}
function communityTime(t){return t?new Date(t*1000).toLocaleString('zh-CN',{hour12:false}):''}
async function communityAPI(path,method='GET',value){if(location.protocol==='file:')throw Error('离线副本可以查阅档案；互助账号与发布需要原站服务。');const opt={method,credentials:'same-origin',headers:{'X-Kanjian-Request':'1'}};if(value!==undefined){opt.headers['Content-Type']='application/json';opt.body=JSON.stringify(value)}let res;try{res=await fetch('/api/community'+path,opt)}catch{throw Error('暂时无法连接，请保留草稿后重试。')}const data=await res.json().catch(()=>({error:'互助服务暂时不可用。'}));if(!res.ok)throw Error(data.error||'操作没有完成。');return data}
function communityGuestEntry(signedIn=false){return `<a class="button primary" href="${signedIn?'/signout-with-chatgpt?return_to='+encodeURIComponent('/#home'):'#home'}"${signedIn?' target="_top"':''}>${signedIn?'切换为游客':'游客进入'}</a>`}
function communityLogin(returnTo='account'){return `<a class="button primary" href="/signin-with-chatgpt?return_to=${encodeURIComponent('/#'+returnTo)}" target="_top">登录后继续</a>`}
function communityMember(){const m=COMMUNITY.me;if(!m?.signedIn)return `<div class="soft-note"><h2>登录后，留下自己的问题</h2><p>先以游客看看也可以。查找与下载无需登录，发帖和回复再使用账号。</p><div class="inline-actions">${communityGuestEntry()}${communityLogin()}</div></div>`;if(!m.profile)return `<div class="soft-note"><h2>先选一个公开昵称</h2><p>昵称用于交流。账号验证、经历真实性与公开授权分别处理。</p><a class="button primary" href="#account">设置昵称与查看公约</a></div>`;return ''}
function renderCommunity(){return `<div class="content-column"><div class="heading-line page-title"><div><h1>互助交流</h1><p class="muted">可以先把问题说出来，也可以帮助别人整理一点。</p></div><a class="button primary" href="#community-write">${icon('pencil-line')}写下问题</a></div><div class="community-toolbar"><label>分类<select id="community-category"><option value="">全部</option>${communityKinds.map(x=>`<option>${x}</option>`).join('')}</select></label><label>地区<input type="text" id="community-region" placeholder="省或市（选填）" maxlength="60"></label><label>排序<select id="community-sort"><option value="waiting">等待回应优先</option><option value="latest">最新进展</option></select></label><button id="community-filter">筛选</button></div><div class="community-links"><a href="#account">${icon('folder-open')}我的帖子与通知</a><a href="#community-rules">${icon('info')}社区公约</a><button class="quiet" id="community-snapshot">${icon('download')}保存获准传播的公开目录</button></div><div id="community-list" aria-live="polite"><p class="muted">正在读取讨论…</p></div><details class="source-details spaced"><summary>查看原有虚构讨论示例</summary>${DATA.topics.map(t=>`<a class="topic-row" href="#topic/${t.id}"><span class="muted">虚构演示 · ${esc(t.tag)}</span><h3>${esc(t.title)}</h3></a>`).join('')}</details></div>`}
function communityTopicCard(t){return `<a class="topic-row" href="#community-topic/${t.id}"><span class="eyebrow">${esc(t.category)}${t.region?' · '+esc(t.region):''}</span><h2>${esc(t.title)}</h2><p>${esc(t.body.slice(0,100))}${t.body.length>100?'…':''}</p><span class="muted">${esc(t.nickname)} · ${communityTime(t.updated)} · ${t.replyCount||0} 条公开回复 · ${communityProgress[t.progress]}</span></a>`}
async function communityList(){try{const params=new URLSearchParams({category:$('community-category')?.value||'',region:$('community-region')?.value.trim()||'',sort:$('community-sort')?.value||'waiting',offset:COMMUNITY.offset});const epoch=COMMUNITY.epoch,d=await communityAPI('/topics?'+params);if(epoch!==COMMUNITY.epoch||!$('community-list'))return;$('community-list').innerHTML=d.topics.length?d.topics.map(communityTopicCard).join(''):`<div class="empty"><h2>这里还没有匹配的讨论</h2><p>可以换一个筛选条件，或先留下自己的问题。</p><a class="button" href="#community-write">写下问题</a></div>`;if(d.hasMore)$('community-list').innerHTML+='<button data-community-next="'+d.nextOffset+'">查看下一页</button>';if(COMMUNITY.offset)$('community-list').innerHTML+='<button id="community-first">回到第一页</button>';}catch(e){if($('community-list'))$('community-list').innerHTML=`<div class="notice">${esc(e.message)}</div><button id="community-retry">重新读取</button>`}}
function renderCommunityShell(title){return `<div class="content-column">${backLink('mutual','互助交流')}<div id="community-surface" aria-live="polite"><h1>${esc(title)}</h1><p class="muted">正在读取…</p></div></div>`}
function communityAsset(a){return `<div class="community-attachment">${a.mime.startsWith('image/')?`<img src="${a.url}" alt="${esc(a.name)}" loading="lazy">`:`<video controls playsinline preload="metadata" src="${a.url}" aria-label="${esc(a.name)}"></video>`}<div><strong>${esc(a.name)}</strong><p class="muted">${communitySize(a.size)} · ${a.visibility==='public'?'申请公开':'仅供审核'} · ${a.status==='approved'?'已检查公开范围':'待检查'}${a.allowExport?' · 允许保存传播':''}</p>${a.source?`<a href="${esc(a.source)}" target="_blank" rel="noopener noreferrer">来源页面</a>`:''}<a href="${a.url}" download="${esc(a.name)}">保存文件</a></div></div>`}
function communityCaseForm(type,tid,kind='report'){return `<details class="source-details"><summary>${kind==='appeal'?'补充说明或申诉':'举报或请求更正'}</summary><form class="community-case-form" data-type="${type}" data-id="${tid}" data-kind="${kind}"><label class="form-field"><span>原因</span><select name="reason"><option>个人信息或公开授权问题</option><option>广告、重复或无关内容</option><option>骚扰或冒充</option><option>事实或来源需要核对</option><option>对处理结果有异议</option><option>其他</option></select></label><label class="form-field"><span>具体位置、已有来源与希望怎样处理</span><textarea name="details" required maxlength="4000"></textarea></label><p class="muted">说明仅供处理人员查看。举报数量不会自动判定真假。</p><button type="submit">提交${kind==='appeal'?'申诉':'反馈'}</button><p class="community-form-status" role="status"></p></form></details>`}
function communityModForm(type,tid,media=false){return `<details class="source-details"><summary>管理员处理</summary><form class="community-mod-form" data-type="${type}" data-id="${tid}"><label class="form-field"><span>处理原因与对应规则</span><textarea name="reason" required maxlength="2000"></textarea></label>${media?'<label class="check"><input type="checkbox" name="mediaReviewed">已检查申请公开附件的画面、来源与授权范围</label>':''}<div class="inline-actions"><button name="action" value="approve" type="submit">允许公开</button><button name="action" value="needs_changes" type="submit">需要修改</button><button name="action" value="hide" type="submit">暂时隐藏</button></div>${type==='topic'?'<label class="form-field"><span>讨论回复间隔（秒，0关闭）</span><input name="seconds" type="number" min="0" max="3600" value="0"></label><button name="action" value="slow" type="submit">设置慢速回复</button>':''}<p class="community-form-status" role="status"></p></form></details>`}
function communityReply(r){return `<article class="reply" id="reply-${r.id}"><div class="heading-line"><p class="muted">${esc(r.nickname)} · ${communityTime(r.created)}${r.status!=='published'?' · '+communityStatuses[r.status]:''}</p><a href="#community-topic/${r.topic}" data-reply-link="${r.id}">链接</a></div>${r.parent?`<p class="muted">回复上方编号 ${esc(r.parent.slice(0,8))} 的内容</p>`:''}<p class="community-copy">${esc(r.body)}</p>${r.source?`<a href="${esc(r.source)}" target="_blank" rel="noopener noreferrer">来源</a>`:''}${r.reason?`<p class="notice">${esc(r.reason)}</p>`:''}<div class="inline-actions">${r.status==='published'?`<button class="quiet" data-quote="${r.id}">引用回复</button>`:''}${r.own?`<button class="quiet" data-withdraw-reply="${r.id}">撤回回复</button>`:''}</div>${COMMUNITY.me?.profile?(r.own&&r.status!=='published'?communityCaseForm('reply',r.id,'appeal'):r.status==='published'?communityCaseForm('reply',r.id):''):''}${COMMUNITY.me?.moderator?communityModForm('reply',r.id):''}</article>`}
function communityTopic(t){COMMUNITY.topic=t;return `<header class="detail-header"><p class="eyebrow">${esc(t.category)}${t.region?' · '+esc(t.region):''}</p><h1>${esc(t.title||'未命名草稿')}</h1><p class="muted">${esc(t.nickname)} · ${communityTime(t.updated)} · v${t.version} · ${communityStatuses[t.status]}</p>${t.institution?`<p>相关机构：${esc(t.institution)}</p>`:''}</header><p class="notice">${t.verification}${t.reason?'。处理说明：'+esc(t.reason):''}</p><article class="reading"><p class="community-copy">${esc(t.body)}</p>${t.source?`<p><a href="${esc(t.source)}" target="_blank" rel="noopener noreferrer">查看来源页面</a></p>`:''}</article>${t.attachments.map(communityAsset).join('')}<div class="community-links"><button class="primary" data-community-share="${t.id}">${icon('share-2')}分享链接</button>${t.status==='published'&&t.allowExport?`<button data-community-export="${t.id}">${icon('download')}保存获准传播内容</button>`:''}${COMMUNITY.me?.profile&&t.status==='published'?`<button data-subscribe="${t.id}" data-enabled="${t.subscribed?'0':'1'}">${t.subscribed?'取消关注':'关注后续回复'}</button>`:''}</div>${t.own?`<div class="soft-note"><h2>我的帖子</h2><p>修改正文会先回到草稿，重新提交后检查公开范围。</p><div class="inline-actions"><a class="button" href="#community-write/${t.id}">编辑与补充</a><button data-withdraw-topic="${t.id}">撤回公开展示</button><select id="community-progress" aria-label="更新求助进展">${Object.entries(communityProgress).map(([k,v])=>`<option value="${k}"${t.progress===k?' selected':''}>${v}</option>`).join('')}</select><button data-progress="${t.id}">更新进展</button></div>${['hidden','needs_changes'].includes(t.status)?communityCaseForm('topic',t.id,'appeal'):''}</div>`:''}<h2 class="section-head spaced">一起回应</h2>${t.replies.length?t.replies.map(communityReply).join(''):'<p class="muted">还没有公开回复。</p>'}${t.replies.length>=t.replyLimit?'<p class="notice">本页显示前300条回复；不能视为完整讨论。</p>':''}${t.status==='published'?(communityMember()||`<form id="community-reply-form" data-topic="${t.id}"><label class="form-field"><span>想回应或补充什么？</span><textarea name="body" required maxlength="5000"></textarea></label><p id="community-quote" class="muted" hidden></p><input type="hidden" name="parent"><label class="form-field"><span>公开来源（选填）</span><input type="url" class="field" name="source" placeholder="https://"></label><label class="check"><input type="checkbox" name="allowExport">允许这条回复随资料包保存、复制和传播</label><p class="muted">回复将公开展示；请先移除私人联系方式。${t.slowSeconds?'本讨论的回复间隔为 '+t.slowSeconds+' 秒。':''}</p><button type="submit" class="primary">发表回复</button><p class="community-form-status" role="status"></p></form>`):'<p class="muted">主题尚未公开，暂时不能回复。</p>'}${t.status==='published'&&COMMUNITY.me?.profile?communityCaseForm('topic',t.id):''}${COMMUNITY.me?.moderator&&t.status!=='draft'&&t.status!=='withdrawn'?communityModForm('topic',t.id,t.attachments.some(a=>a.visibility==='public'&&a.status==='ready')):''}`}
function communityWrite(t={}){COMMUNITY.files.forEach(f=>URL.revokeObjectURL(f.url));COMMUNITY.draft={...t,id:t.id||crypto.randomUUID()};COMMUNITY.files=[];return communityMember()||`<h1>${t.id?'补充自己的帖子':'写下一个问题'}</h1><p class="muted">不必一次写齐。保存草稿后，可从“我的帖子”继续；提交后才进入公开处理。</p><form id="community-post-form"><label class="form-field"><span>问题标题</span><input type="text" name="title" value="${esc(t.title||'')}" maxlength="120" placeholder="希望大家帮你了解或处理什么？"></label><label class="form-field"><span>想补充的背景</span><textarea name="body" maxlength="10000" placeholder="可以写遇到的情况、已有信息，以及希望得到怎样的帮助。">${esc(t.body||'')}</textarea></label><div class="community-two-fields"><label class="form-field"><span>分类</span><select name="category">${communityKinds.map(x=>`<option${t.category===x?' selected':''}>${x}</option>`).join('')}</select></label><label class="form-field"><span>地区（选填）</span><input type="text" name="region" value="${esc(t.region||'')}" maxlength="60" placeholder="省或市"></label></div><label class="form-field"><span>相关机构（选填）</span><input type="text" name="institution" value="${esc(t.institution||'')}" maxlength="150"></label><label class="form-field"><span>公开来源（选填）</span><input name="source" type="url" class="field" value="${esc(t.source||'')}" placeholder="https://"></label><label class="check"><input name="sensitive" type="checkbox"${t.sensitive?' checked':''}>涉及机构争议、具体个人或需要检查的公开范围</label><label class="check"><input name="allowExport" type="checkbox"${t.allowExport?' checked':''}>允许本帖正文随公开资料包保存、复制和传播</label><p class="muted">这项授权只针对你的正文，不替其他回复者授权。保存草稿不会公开。</p><div id="community-writing-guidance" class="notice" hidden></div><h2 class="section-head spaced">图片与视频（选填）</h2><label class="file-picker">${icon('camera')}从手机相册或文件选择<input id="community-files" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" multiple></label><p class="muted">图片每份10MB、视频每份50MB；每帖最多6份、合计100MB。文件不会自动脱敏。未提交草稿只有你可查看，提交后管理员可审核。</p><div id="community-file-list">${(t.attachments||[]).map(a=>`<div class="community-saved-file"><span>${esc(a.name)} · ${a.visibility==='public'?'申请公开':'仅供审核'}</span><button type="button" data-remove-attachment="${a.id}">移出附件</button></div>`).join('')}</div><label class="check"><input id="community-media-consent" type="checkbox">选入的文件是我有权提交的材料；我已检查涉及人员的公开意愿与信息</label><div class="inline-actions spaced"><button type="button" id="community-save">保存草稿与选入附件</button><button type="submit" class="primary">提交帖子</button><a class="button" href="#account">我的草稿</a></div><p id="community-write-status" role="status"></p></form>`}
function communityReadPost(){const f=$('community-post-form'),d=new FormData(f);return {id:COMMUNITY.draft.id,title:d.get('title'),body:d.get('body'),category:d.get('category'),region:d.get('region'),institution:d.get('institution'),source:d.get('source'),allowExport:d.get('allowExport')==='on',sensitive:d.get('sensitive')==='on'}}
async function communitySave(){if(COMMUNITY.savePromise)return COMMUNITY.savePromise;communityFileChoices();const data=communityReadPost(),status=$('community-write-status'),draft=COMMUNITY.draft,files=COMMUNITY.files,consented=$('community-media-consent').checked;const setStatus=text=>{if(status.isConnected)status.textContent=text};COMMUNITY.savePromise=(async()=>{setStatus('正在保存…');const saved=await communityAPI(draft.saved?'/topics/'+data.id:'/topics',draft.saved?'PATCH':'POST',data);draft.saved=true;const pending=files.filter(x=>!x.saved);if(pending.length&&!consented)throw Error('正文草稿已保存；上传附件前请确认材料的提交与公开意愿。');for(const file of pending){setStatus('正在上传 '+file.file.name+'…');const pub=file.public,exp=file.export,source=(file.source||'').trim(),params=new URLSearchParams({name:file.file.name,visibility:pub?'public':'private',export:pub&&exp?'1':'0',source});const res=await fetch('/api/community/topics/'+data.id+'/attachments?'+params,{method:'POST',credentials:'same-origin',headers:{'X-Kanjian-Request':'1','Content-Type':file.file.type,'X-File-Size':String(file.file.size),'X-Media-Consent':'confirmed'},body:file.file});const body=await res.json();if(!res.ok)throw Error(body.error||'附件上传失败。');file.saved=true;file.id=body.id;}setStatus('已保存到我的草稿，尚未公开。');if(status.isConnected&&COMMUNITY.draft===draft)communityFiles();return saved})();try{return await COMMUNITY.savePromise}finally{COMMUNITY.savePromise=null}}
function communityFiles(){const existing=COMMUNITY.draft.attachments||[];$('community-file-list').innerHTML=existing.filter(a=>!a.removed).map(a=>`<div class="community-saved-file"><span>${esc(a.name)} · ${a.visibility==='public'?'申请公开':'仅供审核'}</span><button type="button" data-remove-attachment="${a.id}">移出附件</button></div>`).join('')+COMMUNITY.files.map((f,n)=>`<div class="community-file-option">${f.file.type.startsWith('image/')?`<img src="${f.url}" alt="选入文件预览">`:`<video src="${f.url}" controls playsinline preload="metadata"></video>`}<strong>${esc(f.file.name)}</strong><span class="muted">${communitySize(f.file.size)}${f.saved?' · 已保存':''}</span><label class="check"><input id="community-file-public-${n}" type="checkbox"${f.public?' checked':''}${f.saved?' disabled':''}>经审核后允许公开这份附件</label><label class="check"><input id="community-file-export-${n}" type="checkbox"${f.export?' checked':''}${f.saved?' disabled':''}>公开后允许保存、复制和传播</label><label class="form-field"><span>原始来源链接（选填）</span><input id="community-file-source-${n}" type="url" class="field" value="${esc(f.source||'')}"${f.saved?' disabled':''}></label><button type="button" data-remove-file="${n}">移出选入文件</button></div>`).join('')}
function communityAccount(){const m=COMMUNITY.me;if(!m?.signedIn)return `<h1>欢迎，先随便看看</h1><p class="muted">游客无需注册，可以查找机构、阅读公开资料并下载保存。</p><div class="inline-actions spaced">${communityGuestEntry()}<a class="button" href="#browse">查看资料</a></div><section class="soft-note"><h2>有资料想补充？</h2><p>不用社区账号也能提供资料、反馈更正，并凭私人回执查看进度。</p><div class="inline-actions"><a class="button" href="#provide">提供资料</a><a class="button" href="#intake-status">查看私人回执</a></div></section><section class="soft-note"><h2>参与互助交流</h2><p>发帖和回复需要登录，方便保存自己的内容和跟进回应。目前使用 ChatGPT 登录。</p>${communityLogin()}</section>`;return `<h1>我的帖子与通知</h1><p class="muted">这里的昵称公开显示，登录账号信息不会随资料包导出。</p><form id="community-profile-form"><label class="form-field"><span>公开昵称</span><input type="text" name="nickname" value="${esc(m.profile?.nickname||'')}" required minlength="2" maxlength="24"></label><label class="check"><input name="acceptRules" type="checkbox" required${m.profile?' checked':''}>我已阅读<a href="#community-rules">社区公约与隐私说明</a></label><button type="submit">${m.profile?'保存昵称':'确认并开始交流'}</button><p class="community-form-status" role="status"></p></form><div class="community-links"><a href="#community-write">写下问题</a>${m.moderator?'<a class="button" href="#intake-mod">资料与反馈核对</a><a class="button" href="#backup">私人备份</a><a class="button" href="#community-mod">处理审核与反馈</a>':''}${communityGuestEntry(true)}</div>${m.profile?.suspendedUntil>Date.now()/1000?`<p class="notice">当前账号暂时禁言至 ${communityTime(m.profile.suspendedUntil)}，仍可查看处理结果和申诉。</p>`:''}<div id="community-mine"></div>`}
async function communityMine(){if(!COMMUNITY.me?.profile||!$('community-mine'))return;const epoch=COMMUNITY.epoch,d=await communityAPI('/mine');if(epoch!==COMMUNITY.epoch||!$('community-mine'))return;$('community-mine').innerHTML=`<h2 class="section-head spaced">通知</h2>${d.notices.length?d.notices.map(n=>`<div class="community-notice"><p>${esc(n.message)}</p><span class="muted">${communityTime(n.created)}</span>${n.topic?`<a href="#community-topic/${n.topic}">查看讨论</a>`:''}${!n.is_read?`<button class="quiet" data-notice-read="${n.id}">标记已读</button>`:'<span class="muted">已读</span>'}</div>`).join(''):'<p class="muted">还没有通知。</p>'}<h2 class="section-head spaced">我的帖子与草稿</h2>${d.topics.length?d.topics.map(t=>`<div class="topic-row"><a href="#${t.status==='draft'?'community-write':'community-topic'}/${t.id}"><h3>${esc(t.title||'未命名草稿')}</h3></a><p class="muted">${communityStatuses[t.status]} · ${communityTime(t.updated)}</p>${t.reason?`<p>${esc(t.reason)}</p>`:''}</div>`).join(''):'<p class="muted">还没有帖子。可以先保存一个草稿。</p>'}<h2 class="section-head spaced">我的回复</h2>${d.replies.map(r=>`<div class="reply"><p>${esc(r.body)}</p><span class="muted">${communityStatuses[r.status]}</span><a href="#community-topic/${r.topic}">查看讨论</a>${r.reason?`<p>${esc(r.reason)}</p>`:''}${['hidden','needs_changes'].includes(r.status)?communityCaseForm('reply',r.id,'appeal'):''}</div>`).join('')||'<p class="muted">还没有回复。</p>'}<h2 class="section-head spaced">举报与申诉结果</h2>${d.cases.map(c=>`<div class="reply"><p>${c.kind==='appeal'?'申诉':'举报'}：${esc(c.reason)}</p><p class="muted">${c.status==='pending'?'等待处理':c.status==='resolved'?'已处理':'未采纳'} · ${communityTime(c.created)}</p>${c.decision?`<p>${esc(c.decision)}</p>`:''}</div>`).join('')||'<p class="muted">还没有提交记录。</p>'}<p class="muted">每类最多显示最近 ${d.limit} 条。</p>`}
function communityModeration(d){return `<h1>审核与反馈</h1><p class="muted">检查公开范围、来源与行为规则。允许展示不等于确认陈述真实。</p><h2 class="section-head spaced">帖子</h2>${d.topics.map(t=>`<div class="topic-row"><a href="#community-topic/${t.id}"><h3>${esc(t.title)}</h3></a><p>${esc(t.body.slice(0,200))}</p><span class="muted">${esc(t.nickname)} · ${communityStatuses[t.status]}</span><p>打开帖子查看附件，再决定公开范围。</p></div>`).join('')||'<p class="muted">没有待处理帖子。</p>'}<h2 class="section-head spaced">回复</h2>${d.replies.map(r=>`<div class="reply"><a href="#community-topic/${r.topic}">所属讨论</a><p>${esc(r.body)}</p>${communityModForm('reply',r.id)}</div>`).join('')||'<p class="muted">没有待处理回复。</p>'}<h2 class="section-head spaced">举报与申诉</h2>${d.cases.map(c=>`<div class="reply"><h3>${c.kind==='appeal'?'申诉':'举报'} · ${esc(c.reason)}</h3><p>${esc(c.details)}</p><p class="muted">${esc(c.nickname)} · ${communityTime(c.created)}</p><a href="#community-topic/${c.topic_id||c.target_id}">查看相关内容</a><form class="community-mod-form" data-type="case" data-id="${c.id}"><label class="form-field"><span>核对结果与处理说明</span><textarea name="reason" required maxlength="2000"></textarea></label><button name="action" value="resolve">已处理并反馈</button><button name="action" value="reject">不采纳并说明</button><p class="community-form-status" role="status"></p></form></div>`).join('')||'<p class="muted">没有待处理举报或申诉。</p>'}<h2 class="section-head spaced">账号发布权限</h2>${d.profiles.map(p=>`<details class="source-details"><summary>${esc(p.nickname)}${p.suspendedUntil>Date.now()/1000?' · 禁言中':''}</summary><form class="community-mod-form" data-type="profile" data-id="${p.publicId}"><label class="form-field"><span>禁言天数（0解除，最多30）</span><input name="days" type="number" value="0" min="0" max="30"></label><label class="form-field"><span>规则及原因</span><textarea name="reason" required maxlength="2000"></textarea></label><button name="action" value="suspend">保存发布限制</button><p class="community-form-status" role="status"></p></form></details>`).join('')}<h2 class="section-head spaced">最近处理记录</h2>${d.audit.map(a=>`<p class="muted">${communityTime(a.created)} · ${esc(a.action)} · ${esc(a.reason)}</p>`).join('')||'<p class="muted">还没有处理记录。</p>'}<p class="muted">各队列最多显示 ${d.limit} 条，处理记录显示最近50条。</p>`}
function renderCommunityRules(){return `<div class="content-column reading-column">${backLink('mutual','互助交流')}<h1>互助社区公约</h1><p class="muted">试用规则 · 2026-10-09-v1</p><article class="reading"><h2>先说明希望得到什么帮助</h2><p>可以求助、交流经历、整理资料和讨论保存传播。文字简短、表达不完整或感谢他人，都不直接视为灌水。来源可以后补，不把求助当作已经确认的机构事实。</p><h2>尊重公开范围</h2><p>公开正文和回复不要写入他人的私人联系方式、身份证件、家庭地址或未经确认的个人信息。图片视频不会自动脱敏，公开前需要检查。公开阅读与资料包传播分别授权，每人只对自己有权提交的内容作出声明。</p><h2>保留来源与不确定的部分</h2><p>亲历、转述和推测分别说明。具体机构争议、疑似私人信息或广告引流会进入审核。机构可提交回应及更正，按相同规则处理。账号验证不代表经历真实。</p><h2>减少重复与骚扰</h2><p>不重复刷屏、不广告引流、不冒充或围攻他人。提交新主题每分钟1次、每天最多2个；回复每30秒1次、每天最多15条；异常讨论可临时慢速回复。新用户首个主题先审核。这些是试用限额，后续按实际使用情况调整。</p><h2>审核、举报和申诉</h2><p>审核可能允许展示、需要修改或暂时隐藏。处理应说明理由，作者可在我的内容中查看并申诉。举报数量不会自动永久删帖或封号。自动筛查只安排待核对队列，不能证明内容真假。</p><h2>账号与隐私说明</h2><p>当前使用ChatGPT平台登录，不在本站收集密码、手机号或身份证。本站保存平台提供的账号标识、公开昵称、内容、授权选择、关注关系和处理记录；身份邮箱只用于核对管理员配置，不写入公开资料包。草稿仅自己可访问，提交后审核人员可查看原件。后台数据由当前站点维护者管理。</p><p>当前开放游客阅读；发帖使用ChatGPT登录，尚未接入国内手机号身份认证。登录账号找回由平台处理。本站目前不提供陌生人私信、收费服务或全天紧急响应。</p><h2>保存、撤回与留存</h2><p>作者可以撤回帖子、回复或附件的展示。撤回后停止由本站提供公开访问；已被其他人保存的旧副本无法保证全部收回。附件限额按后台留存总量累计计算，撤回展示不立即释放空间。审核原件和处理记录会保留在后台，当前尚未设置自动清理周期，真实投稿前需要确定留存和删除流程。未选择传播授权的内容不进入导出包。</p><h2>功能参考</h2><p><a href="https://meta.discourse.org/t/discourse-moderation-guide-part-3-managing-content/406266" target="_blank" rel="noopener">Discourse审核与慢速模式</a>；<a href="https://support.reddithelp.com/hc/en-us/articles/17625458521748-Automations-Post-Comment-Guidance-Set-Up" target="_blank" rel="noopener">Reddit发帖提示</a>。本站参数与流程按本项目调整。</p></article></div>`}
async function communityHydrate(page,tid){const epoch=++COMMUNITY.epoch;try{COMMUNITY.me=await communityAPI('/me');if(epoch!==COMMUNITY.epoch)return;const menu=$('community-account-link');if(menu)menu.textContent=COMMUNITY.me.signedIn?'我的':'登录';if(!['mutual','community-topic','community-write','account','community-mod'].includes(page))return;if(page==='mutual'){COMMUNITY.offset=0;await communityList();return}const surface=$('community-surface');if(!surface)return;if(page==='account'){surface.innerHTML=communityAccount();await communityMine();return}if(page==='community-write'){const t=tid?await communityAPI('/topics/'+tid):{};if(epoch!==COMMUNITY.epoch)return;if(tid&&!t.own)throw Error('只能编辑自己的帖子。');surface.innerHTML=communityWrite(t);if(tid)COMMUNITY.draft.saved=true;return}if(page==='community-topic'){const t=await communityAPI('/topics/'+tid);if(epoch!==COMMUNITY.epoch)return;surface.innerHTML=communityTopic(t);const target=new URL(location.href).searchParams.get('reply');if(target)$('reply-'+target)?.scrollIntoView({block:'center'});return}if(page==='community-mod'){if(!COMMUNITY.me.moderator)throw Error('只有管理员可以处理审核。');if(!COMMUNITY.me.profile){surface.innerHTML=communityMember();return}const d=await communityAPI('/mod/queue');if(epoch===COMMUNITY.epoch)surface.innerHTML=communityModeration(d);}}catch(e){const s=$('community-surface')||$('community-list');if(epoch===COMMUNITY.epoch&&s)s.innerHTML=`<div class="notice">${esc(e.message)}</div><a class="button" href="#account">我的账号</a>`}}
function communityFileChoices(){COMMUNITY.files.forEach((f,n)=>{f.public=$('community-file-public-'+n)?.checked||false;f.export=$('community-file-export-'+n)?.checked||false;f.source=$('community-file-source-'+n)?.value||''})}
async function communityExport(tid){const d=await communityAPI('/topics/'+tid+'/export'),enc=new TextEncoder(),files=[],media=[];let total=0;for(const a of d.attachments){total+=a.size;if(total>20*1024*1024)break;const res=await fetch(a.url);if(!res.ok)throw Error('附件暂时不可用，资料包未完成。');const bytes=new Uint8Array(await res.arrayBuffer());const name='media/'+a.id+({ 'image/jpeg':'.jpg','image/png':'.png','image/webp':'.webp','video/mp4':'.mp4','video/webm':'.webm'}[a.mime]||'');files.push({name,bytes});media.push({...a,file:name});}if(total>20*1024*1024){saveBlob('互助-'+tid+'-来源目录.json',new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));notify('获准附件超过20MB，已保存文字与来源目录；附件请逐份保存。');return}const t=d.topic,html=`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${esc(t.title)} · 戒网瘾机构观察</title><style>body{font:17px/1.8 system-ui;margin:24px auto;padding:0 18px;max-width:760px;color:#20304a}h1{font-size:28px}p{white-space:pre-wrap}img,video{max-width:100%}article{border-top:1px solid #dde3eb;padding:12px 0}a{color:#165ad5}</style><h1>${esc(t.title)}</h1><p>${esc(t.nickname)} · v${t.version}\n${esc(d.notice)}</p><p>${esc(t.body)}</p>${media.map(a=>a.mime.startsWith('image/')?`<img src="${a.file}" alt="${esc(a.name)}">`:`<video src="${a.file}" controls></video>`).join('')}${d.replies.map(r=>`<article><strong>${esc(r.nickname)}</strong><p>${esc(r.body)}</p>${r.source?`<a href="${esc(r.source)}">来源</a>`:''}</article>`).join('')}<p><a href="${esc(location.origin+d.sourcePath)}">原站与更正</a></p></html>`;files.push({name:'index.html',bytes:enc.encode(html)},{name:'public-record.json',bytes:enc.encode(JSON.stringify({...d,attachments:media},null,2))},{name:'先读我.txt',bytes:enc.encode(d.notice+'\n解压后打开index.html。仅含获准传播的公开内容，不含身份信息和私人原件。\n原站：'+location.origin+d.sourcePath)});const hashes=[];for(const file of files){const hash=new Uint8Array(await crypto.subtle.digest('SHA-256',file.bytes));hashes.push(Array.from(hash,x=>x.toString(16).padStart(2,'0')).join('')+'  '+file.name)}files.push({name:'SHA256SUMS.txt',bytes:enc.encode(hashes.join('\n')+'\n')});saveBlob('看见-互助-'+tid+'.zip',zipFiles(files));notify('已保存获准传播的内容与来源。')}
document.addEventListener('input',e=>{if(!e.target.closest('#community-post-form'))return;const form=$('community-post-form'),text=form.elements.title.value+' '+form.elements.body.value;const box=$('community-writing-guidance');if(box){box.hidden=!/(1[3-9]\d{9}|微信|身份证|家庭住址|保证治愈|收费)/.test(text);box.textContent='内容可能包含联系方式或需要核对的说法。请检查公开范围；这些提示不会自动认定违规。'}});
document.addEventListener('change',e=>{if(e.target.id!=='community-files')return;communityFileChoices();const files=[...e.target.files];for(const file of files){const existing=(COMMUNITY.draft.attachments||[]).filter(a=>!a.removed).length;if(COMMUNITY.files.length+existing>=6){notify('每帖最多6个附件。');break}if(!['image/jpeg','image/png','image/webp','video/mp4','video/webm'].includes(file.type)||file.size>(file.type.startsWith('image/')?10:50)*1024*1024){notify('文件格式或大小不符合当前上传范围。');continue}COMMUNITY.files.push({file,url:URL.createObjectURL(file),saved:false,public:false,export:false})}communityFiles();e.target.value=''});
document.addEventListener('submit',async e=>{const f=e.target;if(!['community-profile-form','community-post-form','community-reply-form'].includes(f.id)&&!f.matches('.community-case-form,.community-mod-form'))return;e.preventDefault();const button=e.submitter,d=Object.fromEntries(new FormData(f)),status=f.querySelector('.community-form-status')||$('community-write-status');if(button)button.disabled=true;try{if(f.id==='community-profile-form'){await communityAPI('/profile','POST',{nickname:d.nickname,acceptRules:d.acceptRules==='on'});await communityHydrate('account');notify('昵称与社区公约已保存。')}else if(f.id==='community-post-form'){await communitySave();const r=await communityAPI('/topics/'+COMMUNITY.draft.id+'/submit','POST',{});notify(r.message);location.hash='community-topic/'+r.id;}else if(f.id==='community-reply-form'){const r=await communityAPI('/topics/'+f.dataset.topic+'/reply','POST',{id:crypto.randomUUID(),body:d.body,source:d.source,parent:d.parent||null,allowExport:d.allowExport==='on'});await communityHydrate('community-topic',f.dataset.topic);notify(r.status==='pending'?'回复已提交，等待检查公开范围。':'回复已发布。')}else if(f.matches('.community-case-form')){const r=await communityAPI('/cases','POST',{kind:f.dataset.kind,targetType:f.dataset.type,targetId:f.dataset.id,reason:d.reason,details:d.details});status.textContent=r.duplicate?'同一内容已有待处理记录，可以到我的内容查看。':'已记录，可到我的内容查看处理结果。';f.reset();}else{await communityAPI('/mod/action','POST',{targetType:f.dataset.type,targetId:f.dataset.id,action:button.value,reason:d.reason,seconds:Number(d.seconds),days:Number(d.days),mediaReviewed:d.mediaReviewed==='on'});const [page,tid]=location.hash.slice(1).split('/');await communityHydrate(page,tid);notify('处理结果已保存。')}}catch(err){if(status)status.textContent=err.message;else notify(err.message)}finally{if(button)button.disabled=false}});
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;try{if(['community-filter','community-first','community-retry'].includes(b.id)){COMMUNITY.offset=0;await communityList()}if(b.dataset.communityNext){COMMUNITY.offset=Number(b.dataset.communityNext);await communityList()}if(b.id==='community-save')await communitySave();if(b.id==='community-snapshot'){const d=await communityAPI('/export');saveBlob('看见-互助公开目录.json',new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));notify(d.complete?'已保存获准传播的公开目录。':'目录仅含最近200个主题，尚非完整副本。')}if(b.dataset.communityExport){b.disabled=true;try{await communityExport(b.dataset.communityExport)}finally{b.disabled=false}}if(b.dataset.communityShare){const url=location.origin+location.pathname+'#community-topic/'+b.dataset.communityShare;if(navigator.share)await navigator.share({title:COMMUNITY.topic?.title||'看见互助',url});else{try{await navigator.clipboard.writeText(url);notify('已复制讨论链接。')}catch{saveBlob('讨论链接.txt',new Blob([url],{type:'text/plain'}));notify('已保存链接说明。')}}}if(b.dataset.subscribe){await communityAPI('/topics/'+b.dataset.subscribe+'/subscribe','POST',{subscribe:b.dataset.enabled==='1'});await communityHydrate('community-topic',b.dataset.subscribe)}if(b.dataset.quote){e.preventDefault();const form=$('community-reply-form');if(!form){notify('请先登录并设置昵称。');return}form.elements.parent.value=b.dataset.quote;$('community-quote').hidden=false;$('community-quote').textContent='正在回应上方回复，原文语境会保留。';form.elements.body.focus()}if(b.dataset.replyLink){e.preventDefault();const u=new URL(location.href);u.searchParams.set('reply',b.dataset.replyLink);try{await navigator.clipboard.writeText(u.href);notify('已复制这条回复的位置链接。')}catch{saveBlob('回复链接.txt',new Blob([u.href]))}}if(b.dataset.noticeRead){await communityAPI('/notices/'+b.dataset.noticeRead,'PATCH',{});await communityMine()}if(b.dataset.progress){await communityAPI('/topics/'+b.dataset.progress,'PATCH',{progress:$('community-progress').value});await communityHydrate('community-topic',b.dataset.progress)}if(b.dataset.withdrawTopic){await communityAPI('/topics/'+b.dataset.withdrawTopic,'DELETE');await communityHydrate('community-topic',b.dataset.withdrawTopic);notify('已停止本帖公开展示；旧副本仍可能存在。')}if(b.dataset.withdrawReply){await communityAPI('/replies/'+b.dataset.withdrawReply,'DELETE');await communityHydrate('community-topic',COMMUNITY.topic.id);notify('回复已撤回。')}if(b.dataset.removeAttachment){await fetch('/api/attachments/'+b.dataset.removeAttachment,{method:'DELETE',headers:{'X-Kanjian-Request':'1'}}).then(async r=>{if(!r.ok)throw Error((await r.json()).error)});COMMUNITY.draft.attachments=COMMUNITY.draft.attachments?.map(a=>a.id===b.dataset.removeAttachment?{...a,removed:true}:a);communityFileChoices();communityFiles();notify('附件已停止展示。')}if(b.dataset.removeFile){communityFileChoices();const n=Number(b.dataset.removeFile),file=COMMUNITY.files[n];if(file.saved){const r=await fetch('/api/attachments/'+file.id,{method:'DELETE',headers:{'X-Kanjian-Request':'1'}});if(!r.ok)throw Error((await r.json()).error)}URL.revokeObjectURL(file.url);COMMUNITY.files.splice(n,1);communityFiles()}}catch(err){if(err.name!=='AbortError'){if($('community-write-status'))$('community-write-status').textContent=err.message;else notify(err.message)}}});
